10	use typst::syntax::{LinkedNode, SyntaxMode};
11	use typst::text::{
12	    AxisValue, FontAxis, FontFlags, FontInfo, FontStretch, FontStyle, FontWeight,
13	    StandardAxes,
14	};
15	use typst::utils::Protected;
16	use typst_utils::Scalar;
17	
18	use crate::IdeWorld;
19	
20	/// Create a temporary engine and run a task on it.
21	pub fn with_engine<F, T>(world: &dyn IdeWorld, f: F) -> T
22	where
23	    F: FnOnce(&mut Engine) -> T,
24	{
25	    let introspector = EmptyIntrospector;
26	    let traced = Traced::default();
27	    let mut sink = Sink::new();
28	    let mut engine = Engine {
29	        library: world.library(),
30	        world: world.upcast().track(),
31	        introspector: Protected::new(introspector.track()),
32	        traced: traced.track(),
33	        sink: sink.track_mut(),
34	        route: Route::default(),
35	    };
36	
37	    f(&mut engine)
38	}
39	
40	/// Create a short description of a font family.
41	pub fn summarize_font_family<'a>(
42	    variants: impl IntoIterator<Item = &'a FontInfo>,
43	) -> EcoString {
44	    use typst::text::Tag;
45	
46	    let mut count = 0;
47	    let mut variable = false;
48	    let mut has_italics = false;
49	    let mut has_obliques = false;
50	    let mut supports_opsz = false;
51	    let mut weight_range = MetricRange::default();
52	    let mut stretch_range = MetricRange::default();
53	    let mut variations = IndexMap::<Tag, MetricRange<Scalar>>::new();
54	
55	    for info in variants {
56	        let axes = StandardAxes::parse(&info.axes);
57	
58	        variable |= info.flags.contains(FontFlags::VARIABLE);
59	        has_italics |= info.variant.style == FontStyle::Italic || axes.ital.is_some();
60	        has_obliques |= info.variant.style == FontStyle::Oblique || axes.slnt.is_some();

